/** The full-color Codex mark (with its own white rounded background baked in) -
 *  rendered as an <img> from /public, not a currentColor glyph, so it keeps its
 *  brand colors. Parent tiles size it via a `[&_img]` rule or an explicit class;
 *  pair it with a white tile so it reads as the Codex app icon. */
export function CodexColorIcon({className}: {className?: string}) {
    return <img src="/codex-color.svg" alt="Codex" className={className}/>;
}

